import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";

import AdminBookingTable from "../components/AdminBookingTable";
import AdminLayout from "../components/AdminLayout";
import api from "../services/api";
import { formatErrorMessage } from "../utils/errorMessages";

const AdminSchedule = () => {
  const [schedule, setSchedule] = useState(null);
  const [message, setMessage] = useState("");

  useEffect(() => {
    const loadSchedule = async () => {
      try {
        const response = await api.get("/admin/schedule");
        setSchedule(response.data || []);
      } catch (error) {
        setMessage(formatErrorMessage(error.response?.data?.detail, "Could not load schedule."));
        setSchedule([]);
      }
    };

    loadSchedule();
  }, []);

  return (
    <AdminLayout title="Schedule" subtitle="Upcoming and active bookings for your assigned block.">
      {message ? <motion.div className="alert info" initial={{ opacity: 0 }} animate={{ opacity: 1 }}>{String(message)}</motion.div> : null}
      <AdminBookingTable bookings={schedule} />
    </AdminLayout>
  );
};

export default AdminSchedule;
